cat > bot.mjs <<'EOF'
// Weekly digest text gate. Never sends anything; it only decides.
// Rules: opt-out per channel (shared in STATE_DIR) blocks every digest; an invalid
// or missing time zone holds; each digest event id is claimed once so redelivery
// cannot send twice. The digest is a text the customer signed up for, so no
// separate opt-in field is required (the app carries none).

import fs from "node:fs";

const stateDir = () => {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
};

const optKey = (userId, channel) => `optout-${encodeURIComponent(userId)}-${encodeURIComponent(channel)}`;
const sentKey = (userId, channel, id) =>
  `sent-${encodeURIComponent(userId)}-${encodeURIComponent(channel)}-${encodeURIComponent(id)}`;
const isOptedOut = (dir, userId, channel) => gkRead(dir, optKey(userId, channel))?.optedOut === true;

export async function optOut(userId, channel = "sms") {
  gkWrite(stateDir(), optKey(userId, channel), { optedOut: true });
}

export async function trySend({ user, message, now }) {
  const dir = stateDir();
  const channel = message?.channel;
  if (!user?.id || !message?.id || !channel) {
    return { sent: false, reason: "Held: the user id, message id or channel is missing, so consent cannot be checked." };
  }
  if (isOptedOut(dir, user.id, channel)) {
    return { sent: false, reason: `Held by the opt-out rule: this customer opted out of ${channel} texts.` };
  }
  if (typeof user.timezone !== "string" || !gkZoneOk(user.timezone)) {
    return { sent: false, reason: "Held by the time zone rule: the customer's time zone is missing or invalid." };
  }
  if (!gkClaim(dir, sentKey(user.id, channel, message.id))) {
    return { sent: false, reason: "Already handled: this digest event was sent before, so it is not sent again." };
  }
  // An opt-out may have landed while we claimed; give the claim back, nothing left.
  if (isOptedOut(dir, user.id, channel)) {
    gkUnclaim(dir, sentKey(user.id, channel, message.id));
    return { sent: false, reason: `Held by the opt-out rule: this customer opted out of ${channel} texts.` };
  }
  return { sent: true, reason: "Allowed: the customer is subscribed and no rule holds this digest." };
}

export async function handleInbound({ userId, channel = "sms", text, now }) {
  const dir = stateDir();
  if (gkIsStop(text)) {
    gkWrite(dir, optKey(userId, channel), { optedOut: true });
    return { reply: "You are unsubscribed and will get no more texts from us. Reply START to turn them back on." };
  }
  if (gkIsStart(text)) {
    gkWrite(dir, optKey(userId, channel), { optedOut: false });
    return { reply: "You are subscribed again. Reply STOP to unsubscribe, HELP for help." };
  }
  if (gkIsHelp(text)) {
    return { reply: "Weekly digest texts. Reply STOP to unsubscribe, START to resubscribe. Msg and data rates may apply." };
  }
  return { reply: null };
}
